# To the Claude Code session it is pasted into: run this block as it is with the Bash tool, in the background with a timeout of an hour (it waits for its environment to let the ADE's host through, while its ticket lives, and out the pairing's hold), and stay with it until it ends, watching it with the Monitor tool (a watch of 30 minutes, started again if it ends first), to tell the person each line it prints that begins with ADE:, word for word, as it comes.
python3 -I - <<'ADE_CLIENT' &&
import hashlib, os, sys, time, urllib.error, urllib.request
try:
    import cryptography
except ImportError:
    sys.exit("ADE: This session's python3 cannot import cryptography, which the link client needs, so nothing was fetched, installed or run: install it for that python3 with pip, which Allow package managers lets through, then paste the block again.")
URL = "http://127.0.0.1:8765/api/ade/link/client"
UNTIL = 1893456000
told = False
while True:
    try:
        with urllib.request.urlopen(URL, timeout=60) as answer:
            client = answer.read(16 * 1024 * 1024)
        break
    except urllib.error.HTTPError as e:
        sys.exit(f"ADE: no link client from {URL}: HTTP {e.code}; nothing was installed or run.")
    except Exception as e:
        why = getattr(e, "reason", e)
        if not str(why).startswith("Tunnel connection failed: 403"):
            sys.exit(f"ADE: no link client from {URL} ({type(why).__name__}); nothing was installed or run.")
    if time.time() + 10 + 20 > UNTIL:
        if not told:
            print("ADE: A claude.ai environment whose network refuses 127.0.0.1 needs it allowed: in the environment's settings, under Network access, choose Limited and add 127.0.0.1 to Allowed domains, keeping Allow package managers ticked; a running session follows the change within about a minute.", file=sys.stderr, flush=True)
        sys.exit("ADE: The ADE's host, 127.0.0.1, is still refused and the ticket has too little time left to link, so nothing was installed or run: make a new ticket in Linked sessions and paste its block.")
    if not told:
        print("ADE: A claude.ai environment whose network refuses 127.0.0.1 needs it allowed: in the environment's settings, under Network access, choose Limited and add 127.0.0.1 to Allowed domains, keeping Allow package managers ticked; a running session follows the change within about a minute. This block waits for that change: it tries again every 10 seconds while its ticket lives and goes on by itself once the host is let through, so nothing needs pasting again.", file=sys.stderr, flush=True)
        told = True
    time.sleep(10)
if hashlib.sha256(client).hexdigest() != "@CLIENT_SHA256@":
    sys.exit("ADE: The link client the ADE served is not the one the page carries (its sha256 differs), so nothing was installed or run: take the block again from the page the ADE itself serves, which carries the client of its own release.")
home = os.path.join(os.path.expanduser("~"), ".proofpane-ade")
try:
    os.makedirs(home, mode=0o700, exist_ok=True)
    part = os.path.join(home, f"ade_link.py.{os.getpid()}.part")
    with open(part, "wb") as fh:
        fh.write(client)
    os.replace(part, os.path.join(home, "ade_link.py"))
except OSError as e:
    sys.exit(f"ADE: the link client could not be put in {home} ({type(e).__name__}); nothing was run.")
ADE_CLIENT
python3 -I "$HOME/.proofpane-ade/ade_link.py" setup --url http://127.0.0.1:8765 --ticket PP-ABCDEFGH --e2e 0:none --name 'Planner' --kind cloud --ref "https://claude.ai/code/session_${CLAUDE_CODE_REMOTE_SESSION_ID#cse_}"

